import subprocess,re
def old(n): return subprocess.run(['git','show','30db505:.github/answers/adp2/q%03d.txt'%n],capture_output=True,text=True).stdout.split('\n')
def rd(n): return open('adp2/q%03d.txt'%n,encoding='utf-8').read()
def wr(n,t): open('adp2/q%03d.txt'%n,'w',encoding='utf-8').write(re.sub(r'\n{3,}','\n\n',t))
def rep(n,a,b,cnt=1):
    t=rd(n); assert t.count(a)==cnt,(n,a[:50],t.count(a)); wr(n,t.replace(a,b))
def line(n,start):
    L=[l for l in rd(n).split('\n') if l.startswith(start)]; assert len(L)==1,(n,start,len(L)); return L[0]
# q004
rep(4,'(//Указ от 02.07.2021 № 400//)','(//Указ Президента РФ от 02.07.2021 № 400//)')
a=line(4,'- Исполнительные органы субъектов совместно'); b=line(4,'- Их задачи: обобщение')
o=old(4)[59]; first=o[:o.index(' Их задачи:')]
b2=first+b[1:]
assert b2.startswith('- **Высшие должностные лица субъектов** образуют') 
rep(4,a+'\n'+b, b2+'\n'+a)
